/*
 * A209150  Triangle of coefficients of polynomials u(n,x) jointly generated
 *          with A208335; see the Formula section.
 * https://oeis.org/A209150
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   Triangle of coefficients of polynomials u(n,x) generated by *
 *            u(n,x) = u(n‑1,x) + (x+1)*v(n‑1,x), * v(n,x) = x*u(n‑1,x) +
 *            v(n‑1,x) + 1, * with u(1,x)=1, v(1,x)=1. * a(n) is the
 *            flattening of the triangular array of the coefficients of * the
 *            polynomials u(n,x): 1; 2,1; 4,4,1; 7,10,5,1; … * * The r...
 * Range:     u8 n <= 38, u16 n <= 62, u32 n <= 62, u64 n <= 62, u128 n <= 62,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stddef.h>

/* Forward declarations – the build provides seq_t and idx_t. */
extern seq_t a(idx_t n);

/* Internal state – memoised data. */
static seq_t   *triangle = NULL;   /* flattened sequence of u‑coefficients */
static size_t   tri_len   = 0;      /* number of elements stored      */
static size_t   tri_cap   = 0;      /* allocated capacity             */

static seq_t   *prev_u    = NULL;   /* previous row for u            */
static seq_t   *prev_v    = NULL;   /* previous row for v            */
static idx_t     prev_len = 0;      /* number of coefficients in row */

/* Ensure the triangle array can hold at least 'need' elements. */
static void ensure_tri_cap(size_t need)
{
    if (tri_len >= need) return;
    size_t new_cap = tri_cap ? tri_cap : 32;
    while (new_cap < need) new_cap <<= 1;
    tri_cap = new_cap;
    seq_t *tmp = (seq_t *)realloc(triangle, tri_cap * sizeof(seq_t));
    if (!tmp) abort();               /* out of memory */
    triangle = tmp;
}

/* Ensure the previous row arrays can hold 'need' elements. */
static void ensure_prev_cap(idx_t need)
{
    if (need <= prev_len) return;
    idx_t new_cap = need;
    seq_t *tmp_u = (seq_t *)realloc(prev_u, new_cap * sizeof(seq_t));
    seq_t *tmp_v = (seq_t *)realloc(prev_v, new_cap * sizeof(seq_t));
    if (!tmp_u || !tmp_v) abort();
    prev_u = tmp_u;
    prev_v = tmp_v;
    prev_len = need;
}

/* Generate the next row of the triangle after the current prev_len row. */
static void generate_next_row(void)
{
    idx_t n = prev_len + 1;           /* new row length                 */
    ensure_prev_cap(n);

    /* Temporary arrays for the new row. */
    seq_t *next_u = (seq_t *)malloc(n * sizeof(seq_t));
    seq_t *next_v = (seq_t *)malloc(n * sizeof(seq_t));
    if (!next_u || !next_v) abort();

    for (idx_t i = 0; i < n; ++i) {
        seq_t u_val = 0, v_val = 0;

        /* u(n,x) = u(n‑1,x) + (x+1)*v(n‑1,x) */
        if (i < prev_len) u_val += prev_u[i];
        if (i > 0 && i-1 < prev_len) u_val += prev_v[i-1];
        if (i < prev_len) u_val += prev_v[i];

        /* v(n,x) = x*u(n‑1,x) + v(n‑1,x) + 1 */
        if (i > 0 && i-1 < prev_len) v_val += prev_u[i-1];
        if (i < prev_len) v_val += prev_v[i];
        if (i == 0) v_val += 1;

        next_u[i] = u_val;
        next_v[i] = v_val;
    }

    /* Append the new row's coefficients of u to the global triangle. */
    ensure_tri_cap(tri_len + n);
    for (idx_t i = 0; i < n; ++i) {
        triangle[tri_len++] = next_u[i];
    }

    /* Discard the old previous row arrays. */
    free(prev_u);
    free(prev_v);
    /* Make the new row the current previous row. */
    prev_u = next_u;
    prev_v = next_v;
    prev_len = n;
}

/* Public entry point. */
seq_t a(idx_t n)
{
    if (n == 0) return 0;   /* not defined; guard against underflow */

    /* Lazily initialise the first row if necessary. */
    if (prev_len == 0) {
        ensure_prev_cap(1);
        prev_u[0] = 1;
        prev_v[0] = 1;
        ensure_tri_cap(1);
        triangle[tri_len++] = 1;   /* u(1,x)=1 */
        prev_len = 1;
    }

    /* Generate rows until we have at least n elements in the triangle. */
    while (tri_len < n) generate_next_row();

    return triangle[n - 1];
}
